INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (139403, 'spa', 'Un animal bovino individual, ya sea buey de labor o toro sacrificial, distinto d', 'Un animal bovino individual, ya sea buey de labor o toro sacrificial, distinto del colectivo בָּקָר («rebaño»). Central en la tradición legal israelita — las leyes del buey que cornea (Éx 21:28-36) y el mandamiento del descanso sabático (Éx 20:17; Dt 5:14) — y prominente en contextos sacrificiales. El becerro de oro es memorablemente descrito como «un buey que come hierba» (Sal 106:20). El español buey/toro y el alemán Ochse reflejan la doble dimensión agrícola y sacrificial.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (139428, 'spa', 'Experimentar y expresar un gozo intenso y exuberante, frecuentemente en un regis', 'Experimentar y expresar un gozo intenso y exuberante, frecuentemente en un registro de pacto o escatológico. Se aplica de manera singular tanto a sujetos divinos como humanos: Dios mismo ''se regocija sobre'' su pueblo (Dt 28:63; 30:9; Jer 32:41; Sof 3:17), y los redimidos responden con exultación equivalente (Isa 61:10; 65:18; 66:10). En la adoración personal, el salmista ''se goza en tu palabra'' (Sal 119:14, 162). El desierto de Isaías que ''se alegrará y florecerá'' (Isa 35:1) extiende el gozo a toda la creación renovada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (139452, 'spa', 'Lirio, loto', 'Lirio, loto. Lirio o flor semejante al lirio, probablemente un término general para varias especies y no una identificación botánica única, empleado en tres registros superpuestos: belleza romántica en el Cantar de los Cantares (2:1-2, 16; 4:5; 5:13; 6:2-3; 7:3), ornamentación arquitectónica en las columnas y la fuente del Templo de Salomón (1 R 7:19, 22, 26; 2 Cr 4:5), y metáfora profética del florecimiento de Israel (Os 14:6).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (139461, 'spa', 'Susa (la capital persa)', 'Susa (la capital persa). Nombre propio Susa (שׁוּשַׁן), la antigua capital de Elam y residencia invernal de los reyes persas. Las 21 ocurrencias designan la misma ubicación geográfica, frecuentemente como ''Susa la ciudadela'' (Neh 1:1; Est 1:2; Dn 8:2). La ciudad es el escenario de la historia de Ester y del llamado de Nehemías a reconstruir Jerusalén.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (139466, 'spa', 'Lirio o flor', 'Lirio o flor semejante al lirio, empleado tanto como referencia botánica y metáfora de belleza (Cantares) como término técnico litúrgico en los títulos de salmos. En los Salmos 60 y 80, «Susán Edut» («lirio del testimonio») parece ser una indicación musical cuyo significado preciso ya era incierto en la antigüedad, lo cual explica la traducción mixta entre «lirio» y «testimonio» en distintos idiomas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (139467, 'spa', 'Nombre propio', 'Nombre propio de un fundador de clan efraimita mencionado en Números 26:35-36 y 1 Crónicas 7:20-21. Las variaciones ortográficas en el texto hebreo se conservan en algunos manuscritos. Como ancestro de clan, su nombre identificaba una subdivisión dentro de la tribu de Efraín. La transliteración consistente en diversos idiomas confirma que se reconoce como nombre propio y no como sustantivo común.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (139471, 'spa', 'Librar, rescatar', 'Librar o rescatar a alguien de un peligro mortal, con Dios como agente habitual. Las nueve ocurrencias aparecen en las secciones arameas de Daniel: seis en la narrativa del horno (Dn 3:15, 17 dos veces, 28) y tres en el relato del foso de los leones (Dn 6:14, 17, 21, 28). El verbo enmarca la pregunta teológica central de ambas narrativas: si Dios es capaz y está dispuesto a rescatar a los fieles.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (139477, 'spa', 'Mirar o vislumbrar', 'Los tres usos incluyen ojos que ven o vislumbran (Job 20:9, 28:7) y la acción del sol sobre el hablante (Cantares 1:6). Las traducciones divergen sobre si Cantares 1:6 significa ''abrasó'' o ''miró'', con el español usando tanto ''quemar'' (abrasar) como ''ver'' (ver). Los pasajes de Job claramente involucran vista o vislumbre, mientras que el contexto agrícola del texto de Cantares (quemada por el sol por trabajo al aire libre) puede apoyar tanto mirar como abrasar, reflejando ambigüedad semántica genuina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (139478, 'spa', 'Torcido o trenzado', 'Torcido o trenzado. Torcido o trenzado, describiendo hilo de lino fino cuyas hebras se tuercen juntas para darle resistencia y belleza. Cada ocurrencia es un participio Hofal en las narrativas de construcción del tabernáculo (Éx 26–39), formando la frase técnica ''lino fino torcido'' (שֵׁשׁ מָשְׁזָר) para cortinas, velos, mamparas y vestiduras sacerdotales.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (139482, 'spa', 'Sustantivo masculino para el soborno en contextos judiciales', 'Sustantivo masculino para el soborno en contextos judiciales. La Torá lo prohíbe categóricamente: el soborno ciega a los sabios (Éx 23:8; Dt 16:19) y Dios no acepta soborno (Dt 10:17). Los profetas denuncian a quienes lo aceptan (Isa 1:23; Miq 3:11). La literatura sapiencial observa su poder como ''piedra encantada'' (Prov 17:8) mientras lo condena (Prov 17:23). También abarca pagos políticos entre reyes (1 Re 15:19).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (139491, 'spa', 'Nadar o empapar', 'Los tres usos incluyen imagen de natación/nadador en Isaías 25:11 (apareciendo dos veces en el versículo) y empapar una cama con lágrimas en el Salmo 6:6. El español usa ''nadar'' y ''inundar'' (inundar/empapar), mientras las traducciones luchan con la difícil metáfora de natación de Isaías para juicio divino. El pasaje del Salmo emplea lenguaje hiperbólico de lamento—lágrimas tan copiosas que empapan la ropa de cama, mostrando inundación emocional expresada mediante saturación líquida literal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (139492, 'spa', 'Postrarse, adorar', 'El sentido dominante del Hitpael reflexivo: postrarse, inclinarse en adoración o en señal de acatamiento. Abarca casi las 173 ocurrencias e incluye la postración ante Dios en adoración (Éx 34:8, Sal 95:6), ante ídolos (Éx 20:5) y ante superiores humanos como gesto de deferencia social (Gn 18:2, 23:7, 33:3). El español postrarse/inclinarse, el francés se prosterner y el alemán anbeten convergen de forma notable.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (139534, 'spa', 'Inclínate (imperativo)', 'El raro imperativo Qal «inclínate» (Is 51:23), donde los enemigos ordenan a Sion que se postre para que puedan caminar sobre su espalda. No se trata de adoración reflexiva sino de una postura humillante impuesta por opresores. El español incínate y el inglés bow down conservan la fisicidad sin la connotación volitiva de culto propia del Hitpael.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (139564, 'spa', 'Abatir, abrumar', 'El Hifil causativo en Proverbios 12:25: la ansiedad «abate» o «deprime» el corazón. Extensión metafórica donde el movimiento físico de inclinarse se interioriza: el corazón queda doblegado bajo la carga emocional. El español lo abate e inglés weighs it down captan esta transferencia psicológica de la postración corporal a la desolación anímica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (139566, 'spa', 'Hazmerreír, objeto de escarnio — persona ridiculizada o burlada', 'Hazmerreír, objeto de escarnio — persona ridiculizada o burlada. Jeremías lamenta ''he llegado a ser hazmerreír todo el día'' (Jer 20:7), Moab ''será puesto en ridículo'' (Jer 48:26-27), y Job es ''irrisión para sus amigos'' (Job 12:4). La fórmula הָיָה לִשְׂחוֹק reaparece en el juicio profético. El español distingue con claridad entre irrisión y burla para este campo semántico de mofa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (139568, 'spa', 'Risa como respuesta emocional — gozosa, incrédula o vacía', 'Risa como respuesta emocional — gozosa, incrédula o vacía. Dios ''llenará tu boca de risa'' (Job 8:21), la boca de los exiliados ''se llenó de risa'' (Sal 126:2), y Eclesiastés indaga: ''Dije de la risa: es locura'' (Ecl 2:2; 7:3). Proverbios 14:13 observa que ''aun en la risa el corazón puede doler''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (139569, 'spa', 'Diversión, entretenimiento — actividad realizada por placer más que como expresi', 'Diversión, entretenimiento — actividad realizada por placer más que como expresión emocional. Una sola aparición en Proverbios 10:23: ''Hacer maldad es como diversión para el necio''. La raíz שָׂחַק (''jugar'') hace transparente el matiz lúdico, distinguiéndolo tanto de la risa gozosa como de la burla despectiva.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (139578, 'spa', 'Estar abatido, decaído (reflexivo)', 'Estar abatido, decaído (reflexivo). Hitpael reflexivo-emocional: estar abatido interiormente, decaído de espíritu — el célebre sentido del ''alma'' en los Salmos. Cuatro ocurrencias se agrupan en Sal 42–43, todas en el estribillo idéntico: ''¿Por qué te abates, oh alma mía?'' (Sal 42:5, 6, 11; 43:5). El Hitpael reflexivo marca esta angustia como autodirigida, una conversación interior del espíritu consigo mismo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (139579, 'spa', 'Ser postrado (pasivo)', 'Ser postrado (pasivo). Nifal pasivo: ser postrado o humillado por fuerza externa — humillación impuesta desde afuera en vez de elegida o experimentada internamente. Llegará el día en que ''la altivez del hombre será postrada'' (Is 2:9); ''el hombre será abatido y el varón será humillado'' (Is 5:15); la voz del humillado ''será baja desde el polvo'' (Is 29:4).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (139580, 'spa', 'Abatir, humillar (causativo)', 'Abatir, humillar (causativo). Hifil causativo: abatir, hacer inclinar, humillar activamente — Dios o un agente poderoso rebajando deliberadamente al orgulloso. Isaías declara que Dios ''ha abatido'' a los habitantes de las alturas y a la ciudad exaltada (Is 25:12; 26:5). Solo dos ocurrencias, ambas en Isaías, ambas con Dios como sujeto del acto de humillar.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (139581, 'spa', 'Ser humillado, abatido', 'Ser humillado, abatido. Qal estativo/pasivo: ser humillado, abatido, rebajado — el sentido figurado, frecuentemente profético, donde personas, naciones o cosas orgullosas son reducidas a la humillación. La fórmula repetida de Isaías ''la altivez del hombre será abatida'' (Is 2:11, 17) define este grupo, junto con Hab 3:6 donde los montes antiguos ''fueron abatidos'' y Sal 107:39 donde el pueblo ''es humillado por la opresión.''');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (139582, 'spa', 'Inclinarse, postrarse', 'Inclinarse, postrarse. Qal activo: inclinarse físicamente, postrarse en reverencia, sumisión o dolor — la acción corporal básica. Bajo el poder de Dios, los que ayudan a Rahab ''se inclinan'' bajo él (Job 9:13); los impíos ''se postran'' a las puertas del justo (Pr 14:19); el salmista ''se inclinaba en duelo'' (Sal 35:14). Las naciones vendrán ''inclinándose'' ante Sion restaurada (Is 60:14).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (139590, 'spa', 'Agacharse, agazaparse', 'Agacharse, agazaparse. Qal de postura animal: agacharse o agazaparse, describiendo la postura física de animales que se agazapan. Job 38:40 retrata a las leonas agachándose en sus guaridas, esperando en emboscada. Una sola ocurrencia, pero translingüísticamente distinta: ninguna traducción emplea vocabulario de adoración o humillación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (139596, 'spa', 'Qal activo', 'Qal activo: degollar un animal, generalmente en contexto ritual o sacrificial — el sentido dominante con 72 ocurrencias, concentradas en Levítico, Números y Éxodo. Abarca el cordero pascual (Éx 12:21), los holocaustos (Lv 1:5, 11), las ofrendas de paz (Lv 3:2, 8), las ofrendas por el pecado (Lv 4:24, 29), y la matanza de animales para alimento tras la victoria militar (1 S 14:32). El español degollar captura la especificidad del acto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (139603, 'spa', 'Nifal pasivo', 'Nifal pasivo: ser degollado — 3 ocurrencias donde el animal es el sujeto gramatical que recibe la acción. En Lv 6:25 la ofrenda por el pecado «ha de ser degollada» (תִּשָּׁחֵט) en el mismo lugar que el holocausto, y Nm 11:22 plantea la pregunta retórica de si todos los rebaños podrían «ser degollados» para alimentar a Israel. El español se degollará confirma la construcción pasiva.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (139606, 'spa', 'Participio pasivo Qal', 'Participio pasivo Qal: el degollado, el animal que ha sido sacrificado — 2 ocurrencias en Lv 14:6 y 14:51 en el ritual de purificación de enfermedades cutáneas, donde el ave viva se sumerge en la sangre del «ave que fue degollada» (הַשְּׁחוּטָה). El español el degollado y el alemán das Geschlachtete sustantivan el participio pasivo, refiriéndose a una matanza ya consumada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (139615, 'spa', 'Participio activo Qal', 'Participio activo Qal: el que degüella, el sacrificador — 2 ocurrencias en las denuncias proféticas de Isaías. En Is 66:3 «el que sacrifica un buey es como el que mata a un hombre», donde la forma participial identifica al agente que realiza el acto. En Is 57:5 la acusación apunta a quienes «degüellan niños en los valles», referencia estremecedora al sacrificio infantil.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (139629, 'spa', 'Uso metafórico extendido', 'Uso metafórico extendido: una lengua o discurso que «degüella» — 1 ocurrencia en Jer 9:8, donde la lengua es descrita como una «flecha matadora» o instrumento letal. La evidencia multilingüe es escasa (español matadora), pero la transferencia metafórica de la carnicería física a la destrucción verbal es notable, trasladando שָׁחַט del ámbito ritual al de la retórica mortal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (139635, 'spa', 'Oro batido o martillado', 'Batido, martillado: describe oro trabajado mediante golpes repetidos y aplicado como revestimiento de escudos. Las cinco apariciones corresponden al participio pasivo Qal en los relatos de los escudos de oro de Salomon (1 R 10:16-17; 2 Cr 9:15-16). El espanol traduce consistentemente ''batido'', apuntando al proceso metalurgico mas que al sentido de degollar.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (139638, 'spa', 'Divieso o úlcera cutánea inflamada que brota en la superficie del cuerpo', 'Divieso o úlcera cutánea inflamada que brota en la superficie del cuerpo. Abarca la sexta plaga de Egipto sobre personas y ganado (Éx 9:9-11), las condiciones cutáneas leprosas bajo inspección sacerdotal (Lv 13:18-23), la temida ''úlcera de Egipto'' como maldición del pacto (Dt 28:27, 35), el divieso casi mortal de Ezequías sanado con una cataplasma de higos (2 R 20:7), y las llagas agónicas de Job en todo su cuerpo (Job 2:7).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (139649, 'spa', 'León (feroz, maduro)', 'Término poético para el león, que evoca fiereza y poder maduro, usado solo en contextos literarios elevados (Job 4:10; 10:16; 28:8; Sal 91:13; Pr 26:13; Os 5:14; 13:7). Se distingue de otros vocablos leoninos como ''aryeh y kephir por su registro de sobrecogimiento y peligro. Dios mismo es comparado con un shachal que acomete contra el Israel descarriado (Os 5:14), mientras Job se describe cazado «como un león» por la divinidad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (139657, 'spa', 'Qal', 'Qal: reirse con desprecio, burlarse o escarnecer. El grupo de sentido mas amplio con 13 ocurrencias. Se usa para la risa desdenosa dirigida a alguien considerado insignificante. Dios se rie de los malvados (Sal 2:4; 59:8), el justo se rie de la caida del arrogante (Sal 52:8), y los que antes eran inferiores a Job ahora se burlan de el (Job 30:1). Destaca la extension figurativa hacia la intrepidez: el caballo de guerra ''se rie'' del peligro (Job 39:22).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (139658, 'spa', 'Piel', 'Piel: jugar, competir fisicamente o retozar. Ocho ocurrencias que abarcan el juego infantil, la competencia atletica y el juego animal. Sanson es sacado para ''divertir'' a los filisteos (Jue 16:25); Abner propone que jovenes ''compitan'' ante los comandantes (2 Sam 2:14); Leviatan juega en el mar (Sal 104:26; Job 40:20).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (139660, 'spa', 'Piel', 'Piel: celebrar con musica, danza y jubilo festivo. Ocho ocurrencias concentradas en los relatos de David. David y todo Israel celebran ante el arca con instrumentos (2 Sam 6:5; 1 Cr 13:8), y David defiende su danza ''delante de YHWH'' (2 Sam 6:21). Las mujeres celebran las victorias de Saul y David (1 Sam 18:7).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (139665, 'spa', 'Qal', 'Qal: reir o sonreir con gozo, placer o alivio. Cinco ocurrencias donde la risa es calida y no despectiva. Job recuerda cuando ''sonreia'' a la gente en sus momentos mas oscuros (Job 29:24); la Sabiduria personificada ''rie'' cuando llega la calamidad (Pr 1:26), pero como vindicacion. Eclesiastes nombra ''un tiempo para reir'' junto a ''un tiempo para llorar'' (Ec 3:4).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (139671, 'spa', 'Piel', 'Piel: bromear o hacer chistes, posiblemente con un matiz enganoso. Una sola ocurrencia en Proverbios 26:19, describiendo a alguien que engana a su projimo y luego dice ''!solo estaba bromeando!''. Este sentido se situa en la interseccion del juego y la burla: la risa encubre un dano real, constituyendo un uso pragmatico distinto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (139682, 'spa', 'Hifil participio', 'Hifil participio: reirse con escarnio o ridiculo. Una sola ocurrencia en 2 Cronicas 30:10, donde los mensajeros de Ezequias son ''objeto de burla'' por parte de las tribus del norte. La morfologia causativa del Hifil lo distingue de la burla en Qal del sentido 1, sugiriendo la accion de provocar o inducir la mofa en otros.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (139687, 'spa', 'Pulverizar, moler', 'Moler hasta hacer polvo, pulverizar, triturar en partículas finas. Se usa para moler incienso (Éx 30:36), para las aguas que desgastan las piedras (Job 14:19) y para aplastar enemigos como polvo (2 S 22:43, Sal 18:42). El verbo enfatiza la reducción completa a polvo: no solo romper sino pulverizar por entero. El uso de David contra sus enemigos es especialmente vívido: derrota total representada como polvo fino.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (139688, 'spa', 'Nubes, nubes tenues', 'Nubes, nubes tenues. Nubes tenues o capa nubosa, las formaciones atmosféricas visibles enfatizadas como delicadas o ligeras. Job 36:28 dice que las nubes ''destilan humedad'' y Job 38:37 pregunta quién puede contarlas. Salmo 57:10 y 108:4 alaban la fidelidad de Dios que se eleva por encima de los שְׁחָקִים. Pasajes clave: Deuteronomio 33:26, Job 35:5, Jeremías 51:9.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (139690, 'spa', 'Cielos, firmamento', 'Cielos, firmamento. Los cielos, firmamento o bóveda celeste entendidos como la vasta extensión superior, usados como sinónimo poético de שָׁמַיִם. Salmo 89:6 pregunta ''¿quién en los cielos se puede comparar con el SEÑOR?'' y Job 37:18 se maravilla de Dios que ''extendió los cielos, firmes como un espejo fundido.'' El singular en Salmo 89:37 identifica al cielo mismo como testigo fiel.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (139697, 'spa', 'Polvo fino, polvo menudo', 'Polvo fino, polvo menudo. Polvo fino o partículas menudas, el vestigio más literal de la raíz שָׁחַק (''moler, pulverizar''). Isaías 40:15 compara las naciones con שַׁחַק מֹאזְנַיִם — ''polvo de la balanza,'' una cantidad tan insignificante que ni siquiera se registra en la balanza. Esta única ocurrencia ancla todo el campo semántico: las nubes son vapor ''molido fino,'' y el polvo es el residuo molido de la materia sólida.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (139701, 'spa', 'Buscar con ahínco (Piel)', 'Buscar con ahínco o diligencia en la forma Piel, el uso principal que abarca todas las formas finitas, infinitivos y participios de búsqueda intensificada. Se emplea característicamente para buscar a Dios con urgencia y devoción: Salmo 63:1 (''De madrugada te busco''), Salmo 78:34 (''buscaban a Dios''), Job 8:5 (''si tú buscares a Dios''). También se extiende a la búsqueda diligente de objetos no divinos como la disciplina en Proverbios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (139709, 'spa', 'Buscar diligentemente (Qal)', 'La forma participial Qal que significa ''el que busca con diligencia'': un hápax en Proverbios 11:27 donde שֹׁחֵר טוֹב (''el que diligentemente busca el bien'') aparece en paralelo con בִּקֵּשׁ y דָּרַשׁ. Aunque semánticamente casi sinónimo del Piel, la forma verbal distinta lo marca como una categoría morfológica separada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (139712, 'spa', 'Sustantivo literal y figurado que significa ''alba, amanecer, primera luz matutin', 'Sustantivo literal y figurado que significa ''alba, amanecer, primera luz matutina.'' Usado con el verbo עָלָה (''subir'') en narrativa (Gn 19:15; 32:25; Jos 6:15; Jue 19:25) y en llamativas figuras poéticas: ''las alas del alba'' para el extremo oriente (Sal 139:9), el alba como símil de esperanza y restauración (Os 6:3; Is 58:8), y ''hijo del alba'' para el resplandor del lucero de la mañana (Is 14:12). En español se traduce alba o aurora.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (139719, 'spa', 'Un único uso verbal denominativo en Is 47', 'Un único uso verbal denominativo en Is 47:11, donde el sustantivo שַׁחַר parece funcionar como verbo Piel con el sentido de ''amanecer'' o ''irrumpir'', describiendo la calamidad que amanece súbitamente sobre Babilonia. Este hapax verbal se traduce de modo anómalo en las distintas versiones (el español su-conjuro sugiere un contexto de conjuro), reflejando la dificultad de este pasaje problemático. La mayoría de los léxicos lo tratan como denominativo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (139724, 'spa', 'Negro, oscuro', 'De color negro u oscuro, describiendo la apariencia fisica observable. La traduccion al espanol distingue entre ''morena'' (Cant 1:5) y ''negro'' (Lev 13:31), revelando un matiz semantico: el termino abarca tanto la descripcion neutra del color (cabello en diagnostico sacerdotal, Lev 13:31, 37; caballos en vision profetica, Zac 6:2, 6) como una oscuridad con carga estetica (la tez bronceada de la amada, Cant 1:5; los cabellos del amado, Cant 5:11).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (139731, 'spa', 'Piel: destruir, arruinar', 'El Piel intensivo: destruir o arruinar con minuciosidad. Dios destruye toda carne con el diluvio (Gn 6:17, 9:11) y las ciudades de la llanura son arruinadas (Gn 13:10, 19:13). Aunque se solapa funcionalmente con el Hifil, el Piel suele enfatizar la completitud o la intensidad de la ruina. El francés détruisit y el español destruir rinden ambas formas de manera similar.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (139732, 'spa', 'Hifil: destruir, aniquilar', 'El sentido causativo dominante del Hifil: destruir, aniquilar o demoler personas, ciudades o tierras. La intercesión de Abraham por Sodoma (Gn 18:28-32), el ángel destructor en Egipto (Éx 12:23) y la aniquilación de ciudades cananeas emplean esta forma. El árabe ahlaka y el coreano 멸하다 transmiten la misma totalidad de destrucción causativa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (139746, 'spa', 'Hifil: corromper', 'El Hifil empleado para la corrupción moral o conductual, no para la destrucción física: «toda carne había corrompido su camino» (Gn 6:12), Israel advertido contra actuar corruptamente (Dt 4:16, 31:29). El árabe afsada («corromper») capta con precisión este sentido ético, distinto de la aniquilación física. El mismo binyan porta ambos significados y exige contexto para distinguirlos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (139757, 'spa', 'Nifal: ser corrompido', 'El Nifal pasivo-reflexivo: volverse corrupto o arruinado. «La tierra estaba corrompida delante de Dios» (Gn 6:11-12) establece el estado que desencadena el diluvio. El cinturón podrido de Jeremías (Jer 13:7) y la vasija estropeada del alfarero (Jer 18:4) ofrecen lecciones objetivas vívidas. El árabe fasada (intransitivo «corromperse») refleja este valor pasivo-estativo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (139758, 'spa', 'Piel: corromper, pervertir', 'El Piel intensivo aplicado a la corrupción moral: causar activamente la ruina moral. «Tu pueblo se ha corrompido» (Éx 32:7, Dt 9:12), y Ezequiel condena al rey de Tiro que «corrompió su sabiduría» (Ez 28:17). Las advertencias deuteronómicas reiteradas muestran cómo esta forma intensiva subraya una degradación moral deliberada y profunda.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (139768, 'spa', 'Piel: echar a perder', 'Un matiz del Piel centrado en echar a perder, malgastar o desperdiciar, más que en la destrucción violenta o la corrupción moral. Onán «derramaba» su simiente (Gn 38:9), y el pariente de Booz teme «arruinar» su heredad (Rut 4:6). Jeremías 13:9 emplea la imagen de pudrir un ceñidor. Este sentido de dejar que algo se malogre añade una coloración económica y doméstica al repertorio del verbo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (139781, 'spa', 'Hofal: ser defectuoso', 'El raro Hofal causativo-pasivo: ser vuelto defectuoso o quedar con tacha. Malaquías condena a quienes sacrifican un animal con defecto (Mal 1:14), y Proverbios 25:26 describe al justo que cede ante el malvado como un manantial enturbiado. El árabe mufsad (participio pasivo) y el coreano 상한 («dañado») captan el estado resultante de menoscabo causado por un agente externo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (139841, 'spa', 'Corrupción o falta', 'Las tres ocurrencias involucran habla corrupta destinada a engañar (Daniel 2:9) y falta buscada pero inexistente en Daniel (6:4, dos veces). El español usa ''corrupta'' (corrupción) y ''falta'' (defecto), mientras que las traducciones varían entre corrupción moral y error administrativo. La repetición en 6:4 enfatiza la intachabilidad de Daniel—a pesar de la investigación hostil, no se pudo encontrar corrupción ni negligencia alguna.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (139842, 'spa', 'Una fosa excavada en el suelo, a menudo como trampa o lazo, y por extensión la f', 'Una fosa excavada en el suelo, a menudo como trampa o lazo, y por extensión la fosa del Seol o la tumba. Ezequiel 19:4,8 la emplea para una trampa literal de leones, mientras que Job 33:18-28 y Salmo 30:10 la usan como figura del reino de la muerte. En español fosa, en francés fosse y en alemán Grube coinciden en la imagen concreta de ''fosa'' a lo largo de 21 apariciones.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (139852, 'spa', 'Un sentido abstracto de corrupción, decadencia o destrucción, derivado de la raí', 'Un sentido abstracto de corrupción, decadencia o destrucción, derivado de la raíz שׁ-ח-ת ''corromper, destruir.'' El Salmo 16:10 declara célebremente que Dios no dejará a su Santo ver ''corrupción'' (Hch 2:27 recoge este sentido en el griego διαφθορά), y el Salmo 55:23 habla de ser llevado a la fosa de destrucción. En español corrupción y destrucción reflejan esta lectura abstracta.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (139857, 'spa', 'Extraviarse moralmente', 'Extraviarse moral o sexualmente, desviandose del camino de la fidelidad, especialmente en el contexto de la infidelidad conyugal. Las cuatro ocurrencias aparecen en Numeros 5:12, 19, 20, 29, en el ritual de la sota para una esposa sospechosa de infidelidad. La frase ''se desvia estando bajo su marido'' (תִּשְׂטֶה תַּחַת אִישָׁהּ) explicita la dimension de fidelidad matrimonial.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (139859, 'spa', 'Apartarse, desviarse', 'Apartarse o desviarse en un sentido mas neutro y direccional, ordenando o instando a la evitacion fisica y moral de un camino danino. En Proverbios 4:15 el padre ordena a su hijo que ''se aparte'' (שְׂטֵה) del camino de los malvados, y en 7:25 advierte que no deje que su corazon ''se incline'' hacia los caminos de la adultera. Aunque persisten los matices morales, el enfasis recae en la evitacion deliberada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (139861, 'spa', 'El árbol de acacia (probablemente Acacia nilotica o seyal), apreciado en el desi', 'El árbol de acacia (probablemente Acacia nilotica o seyal), apreciado en el desierto por su madera dura, duradera y resistente a los insectos. Casi todas sus apariciones lo designan como material de construcción de los objetos más sagrados del tabernáculo: el arca (Éx 25:10), la mesa de los panes de la proposición (Éx 25:23), ambos altares (Éx 27:1; 30:1), los bastidores estructurales (Éx 26:15) y sus varas de transporte (Éx 25:13, 28). Dt 10:3 recuerda que Moisés fabricó el arca de madera de acacia. El único uso no constructivo es Is 41:19, donde Dios promete plantar la acacia junto al cedro y el mirto en el desierto como señal de transformación escatológica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (139863, 'spa', 'Esparcir, extender', 'Extender en superficie, esparcir sobre un area abierta. Los equivalentes en espanol ''esparcir'' (dispersar) y ''extender'' (estirar) captan los dos polos del rango semantico del verbo: dispersar objetos en el espacio (Num 11:32, esparcir codornices para secar; Jer 8:2, huesos esparcidos ante el sol y la luna) y estirar o extender algo (2 Sam 17:19, cubierta extendida sobre un pozo; Job 12:23, Dios expandiendo naciones).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (139870, 'spa', 'Topónimo bíblico', 'Nombre de lugar que significa ''las acacias'', referido principalmente al campamento de Israel al este del Jordán en las llanuras de Moab (Nm 25:1; Jos 2:1; 3:1; Miq 6:5) y secundariamente a un valle al oeste de Jerusalén (Jl 3:18). Las glosas multilingües transliteran uniformemente — español ''Sitim'', francés ''Schittim'' — conservando su condición de nombre propio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (139871, 'spa', 'Guardar rencor', 'Albergar enemistad persistente, guardar rencor o abrigar animosidad contra alguien. Posiblemente relacionado con la raiz detras de ''satan'' (adversario), lo que sugiere una disposicion de oposicion. El espanol ''aborrecer'' y ''odiar'' aproximan el significado, pero el hebreo conlleva un matiz particular de hostilidad sostenida y latente. Usado de Esau contra Jacob (Gen 27:41), del temor de los hermanos de Jose (Gen 50:15), y de la persecucion en Salmos y Job.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (139877, 'spa', 'Acusar, ser adversario', 'Actuar como adversario, acusar u oponerse en sentido cuasi-legal. Derivado del sustantivo ''satán'' (adversario/acusador), este verbo conlleva matices forenses de oposición formal. Las traducciones al español ''adversarios'' y ''acusan'' preservan ese tono judicial. En Zacarías 3:1, el infinitivo ''para acusarle'' describe el rol fiscal del Satán ante el tribunal divino. Los Salmos lo despliegan para enemigos humanos que devuelven bien con hostilidad acusatoria.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (139882, 'spa', 'El Satán', 'El Satán: la figura celestial definida que actúa como acusador y adversario en el consejo divino. Aparece siempre con artículo definido (הַשָּׂטָן) en Job y Zacarías; esta figura recorre la tierra y cuestiona la piedad de los justos (Job 1:6-12; 2:1-7), se presenta para acusar al sumo sacerdote Josué (Zac 3:1-2) e incita a David a censar a Israel (1 Cr 21:1, donde el artículo desaparece). En español se traduce Satán o el Satán.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (139883, 'spa', 'Un adversario humano, oponente político o antagonista militar, usado sin artícul', 'Un adversario humano, oponente político o antagonista militar, usado sin artículo en contextos seculares y bélicos. El ángel de YHWH se convierte en שָׂטָן frente a Balaam (Nm 22:22, 32), Salomón declara que Dios le ha dado descanso de todo adversario (1 R 5:4) y Dios levanta a Hadad y Rezón como adversarios políticos (1 R 11:14, 23, 25). En español se traduce adversario.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (139887, 'spa', 'Un acusador en un contexto legal o forense', 'Un acusador en un contexto legal o forense: quien se coloca a la derecha del acusado para procesarlo. El Salmo 109:6 pide a Dios que ''ponga sobre él un impío, y un acusador (שָׂטָן) esté a su diestra.'' El encuadre judicial — posición a la derecha, paralelismo con ''impío'' — distingue este sentido tanto del Satán celestial como del adversario militar. En español se traduce acusador.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (139891, 'spa', 'Inundacion intransitiva', 'Inundacion intransitiva: aguas que suben y desbordan sus orillas o limites, brotando con abundancia. Frecuentemente metaforico para una invasion militar abrumadora, como cuando Asiria se compara al Eufrates desbordandose hasta llegar al cuello (Is 8:8). Tambien se usa del juicio arrasador de Dios (Is 28:2, 15, 18) y de aguas literales brotando de la roca (Sal 78:20).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (139894, 'spa', 'Arrastre transitivo', 'Arrastre transitivo: aguas desbordadas o fuerzas abrumadoras que barren, arrastran o sumergen activamente a personas o cosas. Domina la perspectiva del que sufre: ''la corriente nos habria arrastrado'' (Sal 124:4), ''no me trague el abismo'' (Sal 69:15). Cantares 8:7 lo usa memorablemente del amor que muchas aguas no pueden arrasar.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (139900, 'spa', 'Nifal pasivo del sentido de lavado', 'Nifal pasivo del sentido de lavado: ser enjuagado o lavado con agua, usado para vasijas que requieren purificacion ritual. Atestiguado en Levitico 15:12, donde una vasija de barro tocada por alguien con flujo debe ser rota, pero una vasija de madera ''sera enjuagada''. La construccion pasiva marca esto como la contraparte receptiva del sentido 3.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (139901, 'spa', 'Enjuagar o lavar un objeto con agua, tipicamente en contextos rituales o domesti', 'Enjuagar o lavar un objeto con agua, tipicamente en contextos rituales o domesticos. Levitico 15:11 prescribe enjuagar las manos; 1 Reyes 22:38 describe el lavado del carro de Acab; Ezequiel 16:9 habla de Dios lavando a Jerusalen con agua. El vocabulario de lavado distingue claramente esta limpieza practica de la violenta imagineria de inundacion.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (139911, 'spa', 'Nifal pasivo del sentido de inundacion', 'Nifal pasivo del sentido de inundacion: ser arrastrado o abrumado por fuerzas desbordantes. Daniel 11:22 lo usa para ejercitos que son arrollados ante un poder emergente. La metafora militar pasiva es distinta del lavado ritual pasivo del sentido 4.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (139913, 'spa', 'Pual pasivo intensivo', 'Pual pasivo intensivo: ser enjuagado o lavado a fondo, indicando una limpieza mas completa que el simple Nifal. Atestiguado en Levitico 6:28 respecto a la vasija de bronce donde se cocio la ofrenda por el pecado, que debe ser fregada y ''enjuagada completamente''. El tallo intensificado senala un grado mayor de limpieza requerido para la pureza sacrificial.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (139914, 'spa', 'Inundación, torrente arrollador', 'Inundación, torrente o avalancha de agua, tanto en sentido literal como metafórico. El español ''inundación'' y ''torrente'' reflejan fielmente el significado central de anegamiento súbito. Job 38:25 presenta el sentido literal: Dios dirigiendo el cauce para el aguacero. En sentido figurado, transmite una fuerza destructiva irresistible — el juicio divino que arrastra enemigos (Nah 1:8), ejércitos invasores que arrasan como riada (Dan 9:26) y la furia desbordada (Prov 27:4).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (139921, 'spa', 'Un oficial cívico, tribal o militar que administra los asuntos comunitarios, org', 'Un oficial cívico, tribal o militar que administra los asuntos comunitarios, organiza al pueblo y hace cumplir las instrucciones junto a jueces y ancianos. Figura prominente en el marco administrativo de Deuteronomio (Dt 1:15; 16:18; 29:9; 31:28) y en las narrativas de la conquista (Jos 1:10; 3:2; 8:33; 23:2; 24:1). En español se traduce oficiales, y las referencias de Crónicas a oficiales del Templo y judiciales (1 Cr 23:4; 26:29; 2 Cr 19:11) confirman este sentido administrativo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (139923, 'spa', 'Un capataz o supervisor puesto sobre trabajadores forzados; específicamente los ', 'Un capataz o supervisor puesto sobre trabajadores forzados; específicamente los capataces israelitas designados por los taskmasters egipcios para supervisar la fabricación de ladrillos (Éx 5:6, 10, 14, 15, 19). Estos hombres ocupaban una posición intermedia: respondían ante los supervisores del faraón, pero eran responsables de su propio pueblo. En español capataces y la expresión ''oficiales de los hijos de Israel'' marcan esta acepción como distinta del sentido cívico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (139935, 'spa', 'Tributo a Yahvé', 'Los tres usos involucran naciones trayendo tributo a Yahvé: Salmo 68:29 (al templo en Jerusalén), 76:11 (al temible), e Isaías 18:7 (desde la lejana Cus). El español usa ''tributo'' y ''presente'', capturando la dimensión de homenaje. El contexto cúltico consistente muestra que estos no son regalos ordinarios sino reconocimientos de la autoridad suprema de Dios, con naciones presentando tesoros ante él.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (139941, 'spa', 'Ancianos comunitarios', 'Título administrativo para los líderes de la comunidad judía durante el período persa, derivado de la raíz aramea que significa ''ser canoso''. Las cinco apariciones se encuentran en las secciones arameas de Esdras (5:5, 9; 6:7, 8, 14), siempre en estado constructo con ''de los judíos''. El español ''ancianos'' traduce con transparencia, reflejando edad y autoridad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (139945, 'spa', 'Canas (literal)', 'Canas (literal). Cabello gris o blanco como rasgo físico y visible del envejecimiento. Lleva connotaciones de dignidad, vulnerabilidad o autoridad según el contexto. Jacob teme que sus ''canas'' desciendan al Seol con dolor (Gn 42:38; 44:29, 31); Proverbios 16:31 llama a las canas ''corona de gloria.'' Oseas 7:9 lo usa como imagen inquietante: las canas se esparcen sobre Efraín sin que él lo sepa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (139949, 'spa', 'Vejez (metonímico)', 'Vejez (metonímico). La vejez misma, usada metonímicamente — las canas representando toda la etapa de la vida. Aparece típicamente con la preposición בְּ (''en la vejez'') o en la frase fija שֵׂיבָה טוֹבָה, ''buena vejez'' (Gn 15:15; 25:8; Jue 8:32; 1 Cr 29:28). La imagen concreta del cabello se ha desvanecido en un concepto temporal abstracto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (139960, 'spa', 'Cal o encalado', 'Cal o encalado: óxido de calcio obtenido al quemar piedra caliza o huesos, usado para recubrir superficies. Deuteronomio 27 prescribe enlucir piedras con cal para inscribir la ley, haciendo el texto visible y permanente. Amós 2:1 condena la quema de huesos hasta convertirlos en cal como acto de profanación. Isaías 33:12 usa la calcinación como metáfora de destrucción completa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (139963, 'spa', 'Meditar, reflexionar', 'Meditar, reflexionar. Meditar, reflexionar o contemplar interiormente — típicamente sobre las obras, la ley o las maravillas de Dios. El Salmo 119 por sí solo concentra la mayoría de las ocurrencias, con el salmista declarando ''en tus mandamientos meditaré'' (119:15), ''tus testimonios son mi meditación'' (119:23, 48), y ''mis ojos se anticipan a las vigilias de la noche para meditar en tu palabra'' (119:148).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (139966, 'spa', 'Quejarse, lamentarse', 'Quejarse, lamentarse. Quejarse, lamentarse o derramar el dolor ante Dios — un acto de habla especializado de angustia. Job resuelve ''me quejaré en la amargura de mi alma'' (Job 7:11), y el salmista gime ''tarde y mañana y a mediodía me quejo y gimo'' (Sal 55:17). Ambos pasajes combinan este verbo con expresiones de turbación interior, señalándolo como angustia vocalizada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (139967, 'spa', 'Hablar, conversar', 'Hablar, conversar. Hablar, conversar o tratar sobre un tema — la dimensión externa y verbal de la raíz. El cántico de victoria de Débora invita a los que cabalgan sobre asnas blancas a ''contarlo'' (Jue 5:10), Job ordena a la tierra que ''hable'' (Job 12:8), y Proverbios personifica a la sabiduría como quien ''hablará contigo'' mientras caminas (Pr 6:22).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (139971, 'spa', 'Considerar profundamente, ponderar (Piel)', 'Considerar profundamente, ponderar (Piel). Piel intensivo: considerar profundamente, ponderar o deliberar con atención sostenida. En Sal 143:5 el salmista ''reflexiona sobre la obra de tus manos,'' intensificando la meditación básica del Qal, mientras Is 53:8 pregunta ''¿quién consideró su generación?'' — una ponderación grave y evaluativa del destino del Siervo. La forma Piel indica que esta reflexión es exhaustiva e intencional, no una meditación casual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (139979, 'spa', 'Queja, lamento o agravio expresado en angustia, típicamente dirigido a Dios', 'Queja, lamento o agravio expresado en angustia, típicamente dirigido a Dios. Es el sentido dominante en Job (7:13; 9:27; 10:1; 21:4; 23:2) y los Salmos (55:2; 64:1; 102:1; 142:2), donde el sufrimiento se vocaliza como una súplica formal. Ana distingue su oración de la embriaguez llamándola ''la abundancia de mi queja'' (1 S 1:16).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (139982, 'spa', 'Meditación o reflexión — contemplación silenciosa y absorta, no agravio vocal', 'Meditación o reflexión — contemplación silenciosa y absorta, no agravio vocal. En el Salmo 104:34, el salmista espera que su ''meditación'' sea agradable a Dios, adoptando una postura contemplativa más que angustiada. Elías usa la palabra con ironía en el Carmelo (1 R 18:27), sugiriendo que Baal quizá esté sumido en sus pensamientos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (139988, 'spa', 'Habla o discurso en sentido general, no técnico', 'Habla o discurso en sentido general, no técnico. En 2 Reyes 9:11, los compañeros de Jehú preguntan por el ''habla'' del profeta: ¿qué dijo aquel loco? Aquí la palabra no lleva carga emocional alguna, solo designa conversación ordinaria, distinta tanto de la queja como de la meditación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (139989, 'spa', 'Arbusto silvestre', 'Arbustos o matorrales silvestres del campo y del desierto, plantas leñosas no cultivadas. Génesis 2:5 los menciona como vegetación que aún no existía antes de la lluvia. Agar pone a Ismael bajo un arbusto en el desierto (Gn 21:15), buscando sombra o escondite. Job 30 asocia los matorrales con los pobres desesperados que se refugian entre ellos. Estas plantas marcan espacios liminales entre el jardín cultivado y el desierto estéril.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (139990, 'spa', 'Meditación en la Torá', 'Dos ocurrencias están en Salmo 119, identificando la Torá (v. 97) y los testimonios (v. 99) como objeto de meditación constante. Job 15:4 lo aplica a ''queja/meditación ante Dios'', posiblemente la crítica de Elifaz a la oración de Job. El español ''meditación'' aparece consistentemente. Los textos del Salmo muestran la meditación como compromiso deleitado y continuo con la instrucción divina, mientras que Job puede involucrar meditación o queja orante.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (139991, 'spa', 'Trampa excavada', 'Los tres usos involucran fosas cavadas por enemigos como trampas: Salmo 57:6 (cavaron una fosa delante de mí), 119:85 (los soberbios cavan fosas), y Jeremías 18:22 (cavaron fosas para atraparme). El español ''fosa'' (hoyo/tumba) y el francés ''fosse'' se alinean a través de los contextos. La variación ketiv/qere en Jeremías muestra incertidumbre textual entre esta palabra y una forma similar, pero el sentido de fosa-trampa permanece consistente en todos los pasajes.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (139992, 'spa', 'Frontera acuática egipcia', 'Cuerpo de agua en la frontera de Egipto, probablemente el brazo oriental del Nilo o un arroyo limítrofe. Sirve como marcador geográfico del extremo sur de Israel (Jos 13:3, 1 Cr 13:5). Isaías 23:3 lo equipara con el Nilo, sugiriendo identificación con sus aguas. Jeremías 2:18 lo usa simbólicamente para referirse a la alianza con Egipto. Ya sea un brazo del Nilo o un arroyo distinto, Sijor señalaba la frontera entre Israel y Egipto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (139996, 'spa', 'Nombre propio del centro cultual principal de Israel en Efrain, sede del taberna', 'Nombre propio del centro cultual principal de Israel en Efrain, sede del tabernaculo desde Josue hasta los inicios de Samuel. Josue establecio alli la Tienda de Reunion (Jos 18:1) y repartio los territorios tribales desde alli (Jos 18:8-10; 19:51). Samuel crecio en Silo bajo Eli (1 Sam 1:3-9; 3:21), y el arca fue llevada desde alli a la batalla (1 Sam 4:3-4). Su destruccion se convirtio en la advertencia de Jeremias a Jerusalen (Jer 7:12-14; 26:6-9).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (140002, 'spa', 'El silonita', 'Adjetivo gentilicio que significa ''el silonita'', designando a una persona procedente de la antigua ciudad santuario israelita de Silo. El español ''el silonita'' y ''el shilonita'' preservan la función gentilicia. Es principalmente un epíteto del profeta Ahías, quien anunció a Jeroboam la secesión del reino del norte (1 R 11:29) y cuya palabra se cumplió en la división (1 R 12:15; 15:29; 2 Cr 9:29; 10:15).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (140007, 'spa', 'Unas 47 ocurrencias emplean el participio de manera sustantivada para designar a', 'Unas 47 ocurrencias emplean el participio de manera sustantivada para designar a un cantor o músico del templo — una persona cuyo papel definido es cantar, especialmente dentro del sistema de adoración levítica. El español los cantores, el alemán Sänger y el francés chanteur reflejan esto. La forma femenina שָׁרוֹת aparece en 2 S 19:35 para las mujeres cantoras. Crónicas, Esdras y Nehemías concentran este uso institucionalizado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (140008, 'spa', 'Unas 40 ocurrencias conservan el sentido verbal activo', 'Unas 40 ocurrencias conservan el sentido verbal activo: el acto de cantar, ya sea en celebración, adoración o lamento. Abarca las conjugaciones Qal y Piel en todas sus formas. La instancia fundacional es Éx 15:1: «Entonces Moisés y los hijos de Israel cantaron (יָשִׁיר) este cántico». El español cantad/cantaré, el alemán singen y el francés chantez confirman la acción verbal pura.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (140036, 'spa', 'Una única ocurrencia en Is 26', 'Una única ocurrencia en Is 26:1 («En aquel día se cantará este cántico en la tierra de Judá») emplea lo que parece ser una forma pasiva o impersonal, diferenciándose tanto del sentido verbal activo como del cantor sustantivado. El español será cantado y el inglés shall be sung confirman el marco pasivo/escatológico en el contexto apocalíptico de Isaías.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (140043, 'spa', 'Canto o composición musical usada en la adoración, la celebración o la expresión', 'Canto o composición musical usada en la adoración, la celebración o la expresión artística, que abarca himnos de alabanza, cánticos de acción de gracias, odas triunfales y poesía lírica. Atestiguado en 78 ocurrencias, desde el cántico de victoria de Débora (Jue 5:12) hasta la música organizada del templo bajo los cantores levíticos de David (1 Cr 6:31; 25:7). El español canto/cántico y el francés cantique subrayan el registro litúrgico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (140053, 'spa', 'El superlativo «Cantar de los Cantares» (Cnt 1', 'El superlativo «Cantar de los Cantares» (Cnt 1:1) — un uso titular único que señala el canto supremo o más excelente, funcionando como designación de género literario para la poesía amorosa de Salomón. El español de los Cantares y el francés des cantiques preservan la construcción superlativa genitiva, indicando que no se trata simplemente de otro canto sino del canto por excelencia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (140072, 'spa', 'Cántico, canción', 'Composición poética formal u oda, cantada en el culto comunitario o en celebraciones nacionales para conmemorar los actos salvíficos de Dios. El Cántico del Mar (Éx 15:1) y el Cántico del Pozo (Nm 21:17) son ejemplos paradigmáticos. El cántico-testamento de Moisés es ordenado por Dios como testimonio contra Israel (Dt 31:19, 21-22, 30).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (140077, 'spa', 'Sisac (faraón egipcio)', 'El faraón egipcio Shoshenq I (ca. 943-922 a.C.), transliterado en hebreo como Sisac. Las ocho apariciones se refieren a este único personaje histórico en dos contextos narrativos: su acogida del fugitivo Jeroboam durante el reinado de Salomón (1 R 11:40), y su invasión de Judá bajo Roboam, cuando saqueó los tesoros del templo y el palacio (1 R 14:25; 2 Cr 12:2, 5, 7, 9).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (140080, 'spa', 'El sentido espacial-posicional central de poner, colocar o situar un objeto, per', 'El sentido espacial-posicional central de poner, colocar o situar un objeto, persona o entidad abstracta en un lugar específico — 54 de 86 ocurrencias en formas Qal activas. Dios pone enemistad (Gn 3:15), Eva nombra a su hijo por la simiente que Dios «puso» (Gn 4:25), y Jacob dirige su rostro hacia Galaad (Gn 31:21). El árabe waḍaʿa y el suajili -weka convergen en este sentido fundacional de colocación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (140081, 'spa', 'Extensión causativo-transformativa que significa hacer, convertir o constituir a', 'Extensión causativo-transformativa que significa hacer, convertir o constituir a alguien o algo en un nuevo estado o función — 24 ocurrencias donde שִׁית funciona como el árabe jaʿala («hacer de»). José es puesto sobre todo Egipto (Gn 41:33), Dios hace de las tinieblas su cubierta (Sal 18:11) y al salmista se le hace habitar en lugares oscuros (Sal 88:6). El paso del «poner» espacial al «convertir» resultativo es sutil pero real.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (140083, 'spa', 'La construcción pasiva donde algo es puesto, impuesto o colocado sobre alguien —', 'La construcción pasiva donde algo es puesto, impuesto o colocado sobre alguien — 3 ocurrencias en contextos legales y cósmicos. Si un rescate «es impuesto» al dueño de un buey que cornea (Éx 21:30), y Dios declara al mar «aquí serán puestas tus olas soberbias» (Job 38:11). El árabe yūḍaʿu y el coreano noh-ida reflejan esta morfología pasiva con precisión.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (140103, 'spa', 'Un sentido especializado de designar, establecer u ordenar a alguien en una capa', 'Un sentido especializado de designar, establecer u ordenar a alguien en una capacidad oficial o disposición fija — 3 ocurrencias donde el enfoque pasa de la mera colocación a la designación institucional. Job suplica que Dios le «señale» un plazo (Job 14:13) y el salmista reconoce que Dios ha «puesto» un rey sobre Sion (Sal 3:6). El árabe ʿayyana y el coreano jeonghada captan el matiz deliberativo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (140117, 'spa', 'Una única ocurrencia en Éxodo 33', 'Una única ocurrencia en Éxodo 33:4, donde Israel, al oír las malas noticias, no «se puso» sus adornos — un acto de duelo tras el episodio del becerro de oro. El versículo emplea el sentido espacial central, pero el contexto de duelo colectivo y desagrado divino le confiere un peso narrativo distintivo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (140129, 'spa', 'Una única ocurrencia en Números 24', 'Una única ocurrencia en Números 24:1, donde Balaam «puso» su rostro hacia el desierto — un modismo para dirigir la atención u orientación. La frase שִׁית פָּנִים («poner el rostro») es paralela al más común שִׂים פָּנִים, pero la elección de שִׁית en el relato oracular de Balaam puede portar un matiz más deliberado y visionario.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (140153, 'spa', 'Espinos, cardos', 'Arbustos espinosos o plantas de cardo que aparecen siempre en los oráculos de juicio de Isaías como parte del par fijo shamir washayit («espinas y cardos»). La expresión describe tierras desoladas e incultas que han pasado de viñedos productivos a páramos bajo la maldición divina (Is 5:6; 7:23-25), o maleza espinosa consumida por el fuego de la ira de Dios (Is 9:18; 10:17; 27:4).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (140158, 'spa', 'Acostarse, dormir', 'El sentido fundamental del Qal: acostarse para descansar, dormir o reposar. Con 183 ocurrencias es el dominante: Samuel acostado en el templo (1 S 3:5, 9), el modismo «acostarse y levantarse» que enmarca la vida cotidiana (Dt 6:7). El árabe ittajaʿa («reclinarse»), el español acostarse y el coreano nuwotda convergen en la postura básica de reposo físico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (140164, 'spa', 'Yacer con (sexual)', 'El sentido eufemístico del Qal para las relaciones sexuales: «yacer con» alguien, siempre marcado por las preposiciones עִם o אֵת. Dieciséis ocurrencias, desde las hijas de Lot (Gn 19:33, 35) hasta la violación de Dina (Gn 34:2) y la casuística legal (Dt 22:22-29). El coreano dongchimhaetda y el árabe dajaʿa maʿa confirman el modismo eufemístico como acepción lexicalizada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (140184, 'spa', 'Hacer acostar', 'El Hifil causativo: acostar a alguien, típicamente en un contexto de cuidado. La mujer sunamita acostó al hijo muerto junto al bastón de Eliseo (2 R 4:21), la madre de Salomón puso a un infante junto a otro (1 R 3:20), Elías acostó al hijo de la viuda en su lecho (1 R 17:19). Siete ocurrencias de colocación deliberada y tierna.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (140190, 'spa', 'Ser tendido (pasivo)', 'El Hofal pasivo-causativo: ser tendido o depositado en posición horizontal. Usado en los oráculos del inframundo de Ezequiel, donde guerreros caídos «son tendidos» entre los incircuncisos muertos (Ez 32:19, 32) y el hijo de la sunamita «fue acostado» en el lecho de Eliseo (2 R 4:32). El árabe yudjaʿu confirma un estado resultante de la acción de otro.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (140218, 'spa', 'Volcar, verter', 'Ocurrencia singular en Job 38:37 con el significado de «volcar» o «inclinar»: «¿Quién puede volcar los cántaros del cielo?». Conserva el cognado árabe antiguo sakaba («verter agua o lágrimas»), por lo demás perdido en hebreo. El español volcar confirma este sentido de descarga de líquido, un fósil léxico que conecta la semántica postural con el vertido desde un recipiente inclinado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (140227, 'spa', 'Ser violada', 'Las formas pasivas del Nifal y el Pual que denotan violación sexual, la contrapartida pasiva del sentido 2 pero con coacción. Isaías 13:16 advierte que las mujeres de Babilonia «serán violadas», Zacarías 14:2 replica el juicio, y Jeremías 3:2 acusa a Israel de prostitución en los caminos. El coreano yok-boirira («será deshonrada sexualmente») confirma la semántica de violencia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (140267, 'spa', 'Emisión de', 'Emisión seminal o ''yacer de simiente'', término técnico de las leyes levíticas de pureza. La frase constructa שִׁכְבַת זֶרַע aparece en regulaciones sobre el contacto sexual (Lv 15:18; 19:20; Nm 5:13) y las emisiones corporales (Lv 15:16-17, 32; 22:4). Funciona como fórmula legal eufemística más que como descripción clínica directa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (140269, 'spa', 'Capa de', 'Una capa o recubrimiento, específicamente de rocío. En Éxodo 16:13-14 el maná apareció después de que ''la capa de rocío'' se evaporara de alrededor del campamento. La misma raíz semántica de ''yacer sobre'' subyace a ambos sentidos, pero aquí describe un depósito físico sobre el suelo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (140270, 'spa', 'Emisión seminal', 'Emisión sexual masculina o cópula, específicamente el acto de «dar la emisión/semen» en contextos prohibidos. Se usa exclusivamente en Levítico 18 y 20 (leyes de santidad que prohíben relaciones con la mujer del prójimo y con animales) y en Números 5 (rito por sospecha de adulterio). La expresión «dar su acostamiento» es lenguaje técnico sacerdotal para el acto sexual desde la perspectiva masculina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (140275, 'spa', 'Pérdida de hijos', 'Los tres usos incluyen dos en Isaías 47:8-9 (Babilonia no conocerá privación de hijos/viudez, pero sí los conocerá) y uno en Salmo 35:12 (me retribuyen con privación/abandono). El español ''orfandad'' (estado de huérfano/privación de hijos) captura la dimensión de pérdida de niños. El uso en Isaías es particularmente contundente—el imperio confiado que reclama inmunidad contra la pérdida experimentará privación completa, mientras el Salmo describe abandono devastador.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (140277, 'spa', 'Privado de crías', 'Privado o despojado de crías, describiendo tanto a animales como a personas que han perdido a sus hijos. El español ''privada de crías'' capta el sentido con precisión. Tres ocurrencias forman el icónico símil de la osa despojada, feroz en su dolor maternal (2 S 17:8; Pr 17:12; Os 13:8). Cantares emplea la negación — ''ninguna privada entre ellas'' — para pintar un cuadro de plenitud reproductiva completa y perfecta armonía.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (140281, 'spa', 'Ebrio, borracho por vino o bebida fuerte, describiendo a una persona que tambale', 'Ebrio, borracho por vino o bebida fuerte, describiendo a una persona que tambalea y ha perdido el dominio propio. Usado literalmente de Nabal en su festín (1 S 25:36), Ela bebiendo (1 R 16:9) y Ana falsamente acusada (1 S 1:13). Empleado figurativamente para naciones que tambalean bajo el juicio divino (Is 19:14; 24:20), vagabundos en la oscuridad (Job 12:25) y marineros sacudidos por la tormenta (Sal 107:27). Joel 1:5 convoca a los borrachos a despertar y llorar.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (140288, 'spa', 'Qal: olvidar', 'El sentido activo fundamental del Qal, con 83 ocurrencias en todas las formas finitas: perfecto, imperfecto, imperativo, cohortativo y consecutivo. Los sujetos humanos olvidan a Dios, el pacto, la ley y las experiencias pasadas; a Dios se le implora que no olvide a su pueblo. Solo Deuteronomio concentra un bloque sustancial de advertencias (4:9, 23; 6:12; 8:11, 14, 19). El árabe nasiya y el coreano itda confirman la universalidad del concepto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (140294, 'spa', 'Nifal: ser olvidado', 'La forma pasiva del Nifal «ser olvidado» en 13 ocurrencias: una persona, un hecho o una cosa se desvanece de la memoria colectiva. Los años de abundancia de José «serán olvidados» (Gn 41:30); los muertos «son olvidados» (Ec 9:5); el salmista clama «soy olvidado como un muerto, fuera de la mente» (Sal 31:12). El español ser olvidado y el alemán vergessen werden marcan con regularidad la voz pasiva.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (140311, 'spa', 'Piel/Hifil: hacer olvidar', 'Las raras formas causativas —Piel perfecto e Hifil infinitivo— que expresan la acción de hacer que alguien olvide, con solo dos ocurrencias. Los falsos profetas «hacen olvidar mi nombre a mi pueblo» con sus sueños (Jer 23:27), y Dios «ha hecho olvidar fiesta y sábado» en la destrucción de Sion (Lm 2:6). El árabe ansā (causar el olvido) refleja con exactitud esta morfología causativa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (140321, 'spa', 'Infinitivo enfático', 'Una ocurrencia del infinitivo absoluto en Deuteronomio 8:19 que funciona como intensificador enfático: «si de veras olvidares (שָׁכֹחַ תִּשְׁכַּח) al Señor tu Dios». La construcción duplicada (infinitivo absoluto + verbo finito) es un recurso clásico de énfasis hebreo. El español «olvidar» refleja la forma infinitiva sin captar la intensificación retórica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (140323, 'spa', 'Nifal: fueron olvidados', 'Una única ocurrencia del Nifal en Eclesiastés 8:10 —los malvados «fueron olvidados» en la ciudad donde habían actuado— segregada por su contexto sintáctico inusual dentro del estilo peculiar de Qohélet. Funcionalmente idéntica al sentido 2 (pasivo «ser olvidado»), el aislamiento de este versículo refleja el algoritmo de agrupamiento más que un significado genuinamente distinto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (140327, 'spa', 'Participio: el que olvida', 'El participio activo del Qal usado como sustantivo para designar a «los que olvidan», una clasificación nominal de agentes marcados por el olvido habitual de Dios. Job 8:13 advierte que «las sendas de todos los que olvidan a Dios» perecen; el Salmo 50:22 amonesta «los que olvidáis a Dios». Solo dos ocurrencias, ambas con un peso teológico de juicio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (140354, 'spa', 'Ser hallado, ser descubierto', 'Ser hallado, ser descubierto. Ser hallado, ser descubierto o salir a la luz (Hitpeel/pasivo). Se usa cuando algo emerge tras un examen o se revela sin énfasis en el esfuerzo del buscador. Daniel 5:11-12 relata que una sabiduría excelente ''fue hallada'' en Daniel; Daniel 2:35 dice que no se halló rastro de la gran imagen. Daniel 5:27 pronuncia el veredicto devastador: ''fuiste pesado y hallado falto.''');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (140356, 'spa', 'Hallar, descubrir', 'Hallar, descubrir. Hallar, descubrir o localizar mediante búsqueda activa o encuentro (Hafel/activo). Arioc busca activamente a Daniel y lo lleva ante Nabucodonosor (Dn 2:25). Esdras 4:15 instruye a los oficiales a buscar en los registros ''y hallarás'' evidencia de rebelión. Esdras 7:16 habla de la plata y el oro ''que puedas hallar'' en la provincia de Babilonia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (140368, 'spa', 'Jornalero, trabajador asalariado', 'Jornalero, trabajador asalariado. Un trabajador asalariado o jornalero — el sentido más común, presente en textos legales, sapienciales y proféticos. Levítico 19:13 y 25:40 establecen los derechos del jornalero bajo la Torá; Job 7:1-2 y 14:6 usan la figura para expresar el cansancio de la existencia humana. Isaías 16:14 y 21:16 invocan ''años de jornalero'' como una medida precisa y estrictamente contada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (140371, 'spa', 'Mercenario, soldado contratado', 'Mercenario, soldado contratado. Soldados mercenarios — tropas extranjeras contratadas. En Jeremías 46:21, los mercenarios de Egipto son comparados con becerros cebados que dan la vuelta y huyen en vez de resistir. Una sola ocurrencia pero semánticamente distinta de la del obrero común.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (140375, 'spa', 'Alquilado, contratado (adjetival)', 'Alquilado, contratado (adjetival). Usado adjetivalmente para describir algo obtenido mediante alquiler en vez de ser propio (Éx 22:15), donde un animal alquilado genera una responsabilidad diferente a la de uno prestado. Este es el sentido más raro, donde el enfoque está en el modo de adquisición más que en una persona.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (140379, 'spa', 'Menguar, aplacarse', 'Disminuir, calmarse, aplacarse — dicho de las aguas del diluvio (Gn 8:1), de la ira real (Est 2:1; 7:10) y posiblemente del agazapamiento de cazadores (Jr 5:26). También se usa para hacer cesar las quejas (Nm 17:5). El español ''se calmó'' y el alemán ''es sanken'' captan el doble registro físico-emocional: las aguas bajan, la cólera se asienta.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (140380, 'spa', 'Ser prudente, ser sabio — prudencia o sabiduría como cualidad estable del caráct', 'Ser prudente, ser sabio — prudencia o sabiduría como cualidad estable del carácter. El árabe فَطِنٌ (perspicaz) y el coreano 슬기로운 (sabio) confirman la dimensión estativa. El Salmo 2:10 exhorta a los reyes a «ser sabios» y el Salmo 101:2 describe caminar de manera «prudente». El énfasis recae en la disposición más que en un acto puntual de comprensión.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (140381, 'spa', 'Los sabios (sustantivo) — participio sustantivado', 'Los sabios (sustantivo) — participio sustantivado: «los sabios» o «los entendidos» como clase reconocida. El árabe الْحُكَمَاءُ (los sabios) y el coreano 지혜로운 자들 confirman el uso nominal. Daniel 11:33, 35 y 12:3 emplean maskilim para los maestros fieles que brillarán como estrellas, un grupo definido tanto por su discernimiento como por su acción justa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (140382, 'spa', 'Prosperar, tener éxito — éxito práctico y prosperidad como fruto de la conducta ', 'Prosperar, tener éxito — éxito práctico y prosperidad como fruto de la conducta sabia. El árabe نجح (najaha = tener éxito) y el suajili -fanikiwa (prosperar) aíslan este sentido orientado al resultado. Josué 1:7-8 promete que la meditación en la Torá conduce a prosperar; 1 Samuel 18:5, 14 relatan que David «tenía éxito» en todas sus misiones.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (140385, 'spa', 'Comprender, entender — captación cognitiva del significado o la importancia de a', 'Comprender, entender — captación cognitiva del significado o la importancia de algo. El árabe فَهِمَ (fahima), el coreano 깨닫다 y el suajili -elewa convergen aquí. El Salmo 14:2 pregunta si alguien «entiende» y busca a Dios. Nehemías 8:13 describe a los líderes reuniéndose «para entender» las palabras de la Torá.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (140390, 'spa', 'Instruir, dar discernimiento — Hifil causativo', 'Instruir, dar discernimiento — Hifil causativo: enseñar, instruir o impartir entendimiento a otro. El árabe عَلَّمَ (enseñar) y أَفْهَمَ (hacer entender) confirman la fuerza causativa. El Salmo 32:8 («Te instruiré») es paradigmático. Nehemías 9:20 atribuye al Espíritu de Dios el haber dado discernimiento al pueblo. Génesis 3:6 señala que el árbol era deseable «para hacer sabio».');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (140392, 'spa', 'Maskil — término de los encabezados sálmicos (Sal 47', 'Maskil — término de los encabezados sálmicos (Sal 47:7), que probablemente designa un canto compuesto con destreza o de carácter contemplativo. Tanto el inglés with a maskil como el español maskil lo dejan transliterado, reflejando la incertidumbre académica. Podría designar un género de salmo sapiencial o una instrucción técnica musical o literaria.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (140395, 'spa', 'Considerar, observar con atención — consideración deliberada y atenta', 'Considerar, observar con atención — consideración deliberada y atenta: mirar algo cuidadosamente y extraer discernimiento. El árabe تَأَمَّلَ (contemplar) y el coreano 살피다 (examinar de cerca) precisan este matiz. El Salmo 41:1 declara bienaventurado al que «considera» al pobre; Job 34:27 condena a quienes no «consideraron» los caminos de Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (140422, 'spa', 'Hábil, certero — una única aparición en Jeremías 50', 'Hábil, certero — una única aparición en Jeremías 50:9 que describe flechas como «hábiles» o «eficaces», es decir, flechas que no fallan. El español hábil capta el sentido transferido. El significado central de la raíz — sabiduría competente — se aplica aquí metafóricamente a la precisión infalible de un arma.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (140435, 'spa', 'Ser privado de hijos (Qal)', 'Ser privado de hijos (Qal). Qal estativo: estar privado de hijos, sufrir la pérdida de los propios hijos. El sujeto experimenta en lugar de causar la pérdida. El doble uso de Jacob en Gn 43:14 (''si he de ser privado de mis hijos, que lo sea'') expresa resignación doliente, mientras Rebeca teme quedar ''privada de vosotros dos'' (Gn 27:45).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (140436, 'spa', 'Causar aborto (Hifil)', 'Causar aborto (Hifil). Hifil causativo: causar aborto, provocar la pérdida del fruto del vientre. Ocurre únicamente en Os 9:14, donde el profeta invoca ''una matriz que aborte y pechos secos'' como juicio divino sobre Efraín. El Hifil intensifica la agencia causativa más allá del Piel, haciendo del sujeto del verbo el instrumento directo de la pérdida del embarazo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (140437, 'spa', 'Privar de hijos, dejar sin hijos (Piel)', 'Privar de hijos, dejar sin hijos (Piel). Piel causativo: privar de hijos, despojar de descendencia, dejar sin hijos mediante la matanza, el juicio o la destrucción. El sujeto — ya sea la espada (Dt 32:25), una bestia salvaje (Lv 26:22) o un decreto divino (Jer 15:7) — inflige activamente la pérdida de hijos vivos. La sentencia de Samuel de que la espada de Agag ''dejó sin hijos a las mujeres'' (1 S 15:33) conlleva esta fuerza causativa con particular severidad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (140441, 'spa', 'Abortar, malparir (Piel)', 'Abortar, malparir (Piel). Piel aplicado al embarazo: abortar, perder la cría, sufrir o causar la pérdida de descendencia no nacida. Se usa tanto de animales como de mujeres — las ovejas de Jacob ''no abortaron'' (Gn 31:38), la promesa del Éxodo ''ninguna abortará en tu tierra'' (Éx 23:26), y la observación de Job de que la vaca del impío ''no aborta'' (Job 21:10).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (140456, 'spa', 'Entendimiento, prudencia', 'Entendimiento, prudencia. Prudencia, discernimiento, entendimiento y sabiduría práctica vistos como una facultad intelectual y moral positiva. Frecuentemente emparejado con בִּינָה (''discernimiento,'' 1 Cr 22:12; 2 Cr 2:11) o modificado por טוֹב (''bueno,'' Pr 3:4; 13:15; Sal 111:10), describe la capacidad de percibir la verdad y actuar rectamente. Nehemías 8:8 lo usa para la claridad expositiva: los levitas ''dieron el entendimiento'' de la Ley.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (140461, 'spa', 'Astucia, sagacidad', 'Astucia, sagacidad. Astucia, sagacidad o inteligencia calculadora empleada para propósitos egoístas o moralmente cuestionables. Atestiguado únicamente en Daniel 8:25, donde el adversario visionario prospera mediante ''su astucia'' (שִׂכְלוֹ), usando la misma facultad de discernimiento para maquinaciones destructivas. Un solo caso, pero semánticamente decisivo como polo negativo de un campo que por lo demás es enteramente positivo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (140470, 'spa', 'Entendimiento extraordinario', 'Los tres usos están en Daniel 5:11, 12 y 14, todos describiendo el entendimiento extraordinario de Daniel en frases similares o idénticas. Aparecen términos como ''entendimiento'' y cognados en español. La repetición a través de estos versículos (testimonio de la reina madre, resumen del rey, luego dirigiéndose directamente a Daniel) enfatiza esta cualidad mediante múltiples testigos. La frase ''perspicacia y entendimiento como la sabiduría de los dioses'' subraya la dimensión sobrenatural de este don.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (140471, 'spa', 'Levantarse temprano, madrugar — el verbo finito Hifil central', 'Levantarse temprano, madrugar — el verbo finito Hifil central: levantarse temprano por la mañana, madrugar para la acción. Las 47 apariciones abarcan relatos patriarcales (Gn 19:27, 20:8, 21:14, 22:3), relatos de conquista (Jos 3:1, 6:12) y situaciones cotidianas (Jue 19:9, 1 S 15:12). El español madrugó, el francés il se leva tôt y el coreano 일찍 일어나다 expresan este acto concreto y físico de levantarse al alba.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (140472, 'spa', 'Madrugar (acción persistente) — el infinitivo absoluto Hifil hashkem usado adver', 'Madrugar (acción persistente) — el infinitivo absoluto Hifil hashkem usado adverbialmente para expresar acción diligente, persistente e insistente, especialmente en la fórmula profética «madrugando y enviando/hablando/advirtiendo». Jeremías emplea este giro repetidamente (7:13, 25; 25:3-4; 26:5; 29:19; 35:14-15; 44:4) y 2 Crónicas 36:15 lo repite. La imagen del amanecer se convierte en metáfora de la urgencia incansable de Dios al llamar a Israel al arrepentimiento.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (140478, 'spa', 'Madrugador (sustantivo/adjetivo) — el participio Hifil usado sustantiva o adjeti', 'Madrugador (sustantivo/adjetivo) — el participio Hifil usado sustantiva o adjetivalmente para quien habitualmente madruga. Isaías 5:11 advierte contra «los que madrugan (מַשְׁכִּימֵי) por la mañana para ir tras la bebida fuerte». El Salmo 127:2 declara vano ser «madrugadores» (מַשְׁכִּימֵי קוּם) sin la bendición del Señor. Oseas 6:4 y 13:3 usan imágenes matinales (rocío, nube) junto con la forma participial para transmitir una devoción efímera.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (140493, 'spa', 'Hombro (parte del cuerpo)', 'Hombro (parte del cuerpo): el hombro físico usado para llevar cargas, soportar yugos o sostener pesos. Génesis 21:14 muestra a Abraham colocando pan y un odre de agua sobre el hombro de Agar; Génesis 9:23 describe a Sem y Jafet poniendo una prenda sobre sus hombros. Isaías 10:27 y 14:25 emplean el hombro figuradamente para referirse a la carga de la opresión.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (140498, 'spa', 'Siquem (nombre de lugar)', 'Siquem (nombre de lugar): el nombre propio Siquem, la antigua ciudad en la región montañosa de Efraín entre el monte Gerizim y el monte Ebal. Génesis 48:22 registra a Jacob dando a José ''un שְׁכֶם por encima de tus hermanos'', un juego de palabras que vincula el nombre de la ciudad con su ''hombro'' o ''cresta'' topográfica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (140502, 'spa', 'Espalda vuelta en obstinación', 'Espalda vuelta en obstinación: extensión figurada en la que ''volver el hombro'' significa dar la espalda en rebeldía o terquedad. Nehemías 9:29 y Zacarías 7:11 emplean esta expresión para describir la negativa de Israel a escuchar a los profetas: dieron un ''hombro rebelde'' y no quisieron oír. Salmo 21:12 habla de hacer que los enemigos ''vuelvan el hombro'', es decir, huyan.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (140506, 'spa', 'Siquem (ciudad) — la antigua ciudad cananea de Siquem, situada entre el monte Ge', 'Siquem (ciudad) — la antigua ciudad cananea de Siquem, situada entre el monte Gerizim y el monte Ebal en la serranía de Efraín, actual Nablus. Un lugar de enorme peso teológico: el primer altar de Abram en Canaán (Gn 12:6), la compra de terreno por Jacob (Gn 33:18-19), la ceremonia del pacto de Josué (Jos 24:1) y el turbulento reinado de Abimelec (Jue 9). Con 62 apariciones, es una de las ciudades nombradas con mayor frecuencia en el Antiguo Testamento.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (140516, 'spa', 'Siquem (persona) — el nombre personal de Siquem, llevado por el hijo de Hamor el', 'Siquem (persona) — el nombre personal de Siquem, llevado por el hijo de Hamor el heveo, un príncipe de la región de la ciudad que agredió a Dina y fue posteriormente asesinado por sus hermanos Simeón y Leví (Gn 34:2-26). Aparece en contextos donde Siquem como persona se distingue de Siquem como ciudad, como en Génesis 34:20, donde el español añade la conjunción «y-Shejem» para señalar el nombre propio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (140522, 'spa', 'Ancestro manasita', 'Los tres usos son genealógicos: Números 26:31 (lista del censo), Josué 17:2 (herencia de tierra), y 1 Crónicas 7:19 (genealogía). El español transliteró el nombre como ''Siquem'' y variaciones. Los ''hijos de Siquem'' o ''Siquem'' aparecen en contextos que establecen estructuras de clanes manasitas y reclamos territoriales. Este nombre personal comparte forma con la ciudad pero se refiere a un antepasado individual, mostrando cómo personas y lugares podían compartir denominación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (140525, 'spa', 'Piel: hacer habitar', 'La forma causativa del Piel: hacer o permitir que alguien habite, o más específicamente, establecer el Nombre de Dios en un lugar elegido. La fórmula distintiva לְשַׁכֵּן שְׁמוֹ שָׁם («para hacer habitar allí su Nombre», Dt 12:11, 14:23, 16:2, 6) es una expresión deuteronómica emblemática. El árabe أُسْكِنُ (forma IV causativa) y el suajili -kalisha son paralelos morfológicos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (140526, 'spa', 'Qal: habitar, morar', 'El sentido básico del Qal: habitar o morar en un lugar como estado continuo. Cubre el rango más amplio: Sem habitando en las tiendas de Jafet (Gn 9:27), Zabulón morando junto al mar (Gn 49:13), Israel habitando en la tierra y Dios morando entre su pueblo (Éx 25:8). El árabe يَسْكُنُ, el español habitará y el coreano 거하다 convergen en la residencia asentada y continua.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (140531, 'spa', 'Participio: morador', 'El participio del Qal usado como sustantivo: «morador, habitante, el que reside». Aparece con cadenas constructas: שֹׁכְנֵי אֹהָלִים («moradores de tiendas», Nm 24:2) o שֹׁכֵן סְנֶה («el que mora en la zarza», Dt 33:16), epíteto de Dios mismo. El árabe سَاكِن y el español el que habita confirman la función de sustantivo participial. El uso teológico en el Salmo 135:21 eleva al morador a título divino.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (140540, 'spa', 'Qal: posarse, reposar', 'Un matiz del Qal que designa el asentarse, posarse o descender temporalmente sobre algo, distinto de la habitación permanente. La nube «se posó» sobre el Tabernáculo (Éx 40:35), «reposó» sobre el campamento (Nm 9:17-18, 22) y la gloria de Dios «se asentó» sobre el Sinaí (Éx 24:16). El árabe لِيَحُلَّ («descender sobre») y el español reposar lo distinguen del habitar ordinario.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (140553, 'spa', 'Hifil: establecer, asentar', 'La forma causativa del Hifil: colocar o asentar a alguien o algo en un lugar por acción de autoridad. Dios «puso» los querubines al este del Edén (Gn 3:24), Josué «estableció» el Tabernáculo en Silo (Jos 18:1) y el salmista advierte contra dejar que la maldad «se asiente» en la tienda (Job 11:14, Sal 7:5). El árabe وَأَسْكَنَ (forma IV) y el español hicieron habitar confirman el rol causativo-agentivo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (140594, 'spa', 'Qal pasivo: ser habitado', 'Un sentido estativo o pasivo del Qal que significa «ser habitado», aplicado a ciudades o regiones que tendrán o no tendrán moradores. Isaías 13:20 declara que Babilonia «nunca más será habitada»; Jeremías 46:26 y 50:39 repiten el mismo oráculo de desolación. El árabe pasivo تُسْكَنُ y el español será habitada confirman la lectura pasiva. Estos usos proféticos revierten con fuerza las connotaciones positivas del verbo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (140619, 'spa', 'Vecino, prójimo', 'Vecino, prójimo: una persona que vive cerca, un vecino o compañero en la comunidad inmediata. El término aparece con diversos sufijos pronominales (su vecino, tus vecinos) enfatizando el vínculo personal y relacional de la cercanía. En Éxodo 12:4 un hombre y su vecino comparten un cordero pascual; en Proverbios 27:10 se prefiere al vecino cercano sobre el hermano lejano.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (140626, 'spa', 'Habitante, residente', 'Habitante, residente: alguien que mora o habita en un lugar determinado, con énfasis en la residencia más que en la proximidad interpersonal. Isaías 33:24 promete que el habitante de Sión no dirá ''estoy enfermo'', y Oseas 10:5 habla de los habitantes de Samaria temblando por el becerro de Bet-avén.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (140635, 'spa', 'Secanías (nombre propio)', 'El nombre personal Secanías/Secanyahu, nombre teofórico que significa ''YHWH ha morado'', portado por varias figuras postexílicas: un descendiente de Jeconías en la línea real (1 Cr 3:21-22; Esd 8:3, 5), un líder que propuso el pacto de arrepentimiento respecto a las esposas extranjeras (Esd 10:2), un jefe de turno sacerdotal (1 Cr 24:11; Neh 12:3, 14), el suegro de Tobías (Neh 6:18) y un levita bajo Ezequías (2 Cr 31:15).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (140640, 'spa', 'Contratar, emplear a sueldo', 'Contratar, emplear a sueldo: el sentido primario en Qal de contratar o emplear a alguien por un salario o servicio, que abarca 17 de las 20 ocurrencias. Cubre un amplio rango transaccional: Raquel contratando a Jacob por la noche con mandrágoras (Gn 30:16), la contratación de soldados mercenarios (2 S 10:6; 1 Cr 19:6-7), artesanos para reparar el Templo (2 Cr 24:12) y el soborno político de consejeros contra Judá (Esd 4:5).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (140650, 'spa', 'Ganar salario', 'Ganar salario: el sentido reflexivo en Hitpael de ganar un salario o sustento mediante el propio trabajo, atestiguado en 2 ocurrencias en Hageo 1:6. Aquí el enfoque pasa del acto del empleador a la perspectiva del trabajador: ''el que gana salario lo echa en saco roto''. La repetición de Hageo en un solo versículo subraya la futilidad del esfuerzo cuando se descuida la casa de Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (140652, 'spa', 'Alquilarse, emplearse', 'Alquilarse, emplearse: un raro sentido reflexivo-pasivo en Niphal de alquilarse o ponerse al servicio como jornalero, en lugar de ser quien contrata. En 1 Samuel 2:5 el cántico de Ana declara que ''los que estaban saciados se alquilaron por pan'', describiendo una reversión de fortunas donde los antes prósperos deben vender su trabajo para sobrevivir.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (140658, 'spa', 'Embriagarse, estar ebrio (Qal)', 'Embriagarse, estar ebrio (Qal): el sentido intransitivo fundamental en Qal: embriagarse o estar en estado de embriaguez por vino o bebida fuerte. La borrachera de Noé en Gn 9:21 es el ejemplo paradigmático. Cantares 5:1 lo emplea en una invitación positiva (''bebed y embriagaos, amados''), mientras que Is 29:9 e Is 49:26 lo despliegan como metáfora de estupor espiritual y juicio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (140659, 'spa', 'Emborrachar, causar embriaguez (Piel/Hifil)', 'Emborrachar, causar embriaguez (Piel/Hifil): el uso factitivo-causativo en las conjugaciones Piel e Hifil: hacer que alguien se emborrache o causar la intoxicación. Este sentido es abrumadoramente teológico: Dios embriaga sus flechas con sangre (Dt 32:42) o hace beber a las naciones de la copa de su ira (Jer 51:7; Is 63:6). La embriaguez deliberada de Urías por David (2 S 11:13) es la única instancia con sujeto humano.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (140669, 'spa', 'Embriagarse a sí mismo (Hitpael)', 'Embriagarse a sí mismo (Hitpael): el sentido reflexivo en Hitpael que aparece únicamente en 1 S 1:14, donde Elí acusa a Ana de haberse embriagado. La conjugación reflexiva enfatiza la agencia personal y la responsabilidad en la intoxicación. El tono acusatorio de la pregunta retórica resalta el matiz de autoinfligimiento.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (140675, 'spa', 'Ebrio, embriagado (adjetival)', 'Ebrio, embriagado (adjetival): un uso adjetival o estativo en Is 51:21, que describe a Jerusalén como ''embriagada, pero no de vino'' — un estado fijo de estupor por el sufrimiento más que por el alcohol. La extensión metafórica tiene una carga teológica profunda: el juicio divino produce un aturdimiento comparable a la ebriedad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (140677, 'spa', 'Recompensa o retribución, frecuentemente de parte de Dios, que trasciende el sim', 'Recompensa o retribución, frecuentemente de parte de Dios, que trasciende el simple pago laboral. Dios se declara a sí mismo el ''galardón sobremanera grande'' de Abram (Gn 15:1), los hijos son llamados ''recompensa'' del Señor (Sal 127:3) e Isaías visualiza a Dios trayendo consigo su recompensa (Is 40:10; 62:11). En español galardón y recompensa distinguen este sentido teológico del salario ordinario.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (140678, 'spa', 'Salario o sueldo concreto pagado por trabajo humano', 'Salario o sueldo concreto pagado por trabajo humano. Es el sentido económico primario, presente en las negociaciones de Jacob con Labán (Gn 30:28-33; 31:7-8), la paga diaria del jornalero (Lv 19:13; Dt 24:15) y la descripción de Ezequiel de los soldados de Nabucodonosor sin paga por el asedio de Tiro (Ez 29:18-19). En español salario y en alemán Lohn traducen consistentemente este sentido.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (140686, 'spa', 'Precio de alquiler o tarifa pagada por un servicio o un pasaje', 'Precio de alquiler o tarifa pagada por un servicio o un pasaje. Jonás pagó la tarifa (שְׂכָרָהּ) de su barco a Tarsis (Jon 1:3) y Éxodo 22:15 trata el precio de alquiler cuando se daña una propiedad prestada. Este sentido de transacción comercial se centra en el costo de un servicio específico, no en un empleo continuo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (140695, 'spa', 'Bebida alcohólica fermentada distinta del vino de uva, que abarca cerveza de ceb', 'Bebida alcohólica fermentada distinta del vino de uva, que abarca cerveza de cebada, vino de dátil y otros licores similares. Casi siempre aparece emparejada con יַיִן (vino) en fórmulas legales y proféticas (Lv 10:9; Is 5:11; Nm 6:3). Prohibida a sacerdotes en servicio y nazareos, pero permitida en la comida sacrificial (Dt 14:26) e incluso recomendada para el afligido (Pr 31:6). En español bebida fuerte, en francés boisson enivrante y en alemán Rauschtrank convergen en un sentido único y claramente delimitado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (140704, 'spa', 'Embriaguez como juicio', 'Los tres usos son todos metafóricos: llenar de embriaguez como juicio (Jeremías 13:13), una copa de embriaguez/desolación (Ezequiel 23:33), y beber sangre hasta la embriaguez (39:19). El español ''embriaguez'' y el francés ''ivresse'' traducen consistentemente el término. Cada contexto emplea embriaguez como imagen de confusión impotente y devastación bajo juicio divino, nunca intoxicación literal. La metáfora comunica pérdida total de control y estabilidad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (140706, 'spa', 'Partícula conectora flexible', 'Los tres usos abarcan causal (2 Reyes 6:11—''a causa de esto''), relativo (Eclesiastés 8:17—''lo que''), y preposicional (Jonás 1:12—''por mi causa''). Las traducciones a menudo lo traducen contextualmente como ''porque'', ''que'', o lo incorporan en frases mayores. La forma muestra influencia del hebreo bíblico tardío, con la partícula funcionando flexiblemente como conector, indicador causal o marcador relativo según el contexto sintáctico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (140709, 'spa', 'Componentes estructurales de bases', 'Las tres apariciones están en 1 Reyes 7:28-29, describiendo componentes de las bases de bronce del templo. Las traducciones varían: el español ''travesaños'' (barras transversales), versiones inglesas usan ''rebordes'', ''marcos'' o ''paneles''. Las referencias repetidas (''entre los marcos'', ''sobre los marcos'') sugieren que estos eran elementos visuales y estructurales prominentes. El contexto describe bases altamente decoradas con leones, bueyes y querubines.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (140711, 'spa', 'Nieve', 'Nieve: la nieve como fenómeno meteorológico literal y como rica imagen figurada. Se usa concretamente para la precipitación y la acumulación de nieve (Job 37:6; Sal 147:16; 148:8), las aguas de deshielo (Job 6:16; 24:19), la nieve almacenada en los depósitos divinos (Job 38:22) y la proverbial constancia de la nieve del Líbano (Jer 18:14). Figuradamente, sirve como el símil bíblico por excelencia de la blancura: la lepra comparada con la nieve (Éx 4:6; Nm 12:10; 2 R 5:27) y la gran promesa de Isaías de que los pecados escarlata serán ''blancos como la nieve'' (Is 1:18).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (140720, 'spa', 'Estar en paz, prosperar', 'Estar tranquilo, en paz, próspero — describiendo un estado de sosiego, aplicado tanto a la paz legítima del fiel (Sal 122:6, ''que estén en paz los que te aman'') como a la perturbadora prosperidad del malvado (Jr 12:1; Job 12:6; Lm 1:5). El español ''prosperan'' capta el matiz material, mientras el inglés ''at ease'' enfatiza la calma psicológica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (140725, 'spa', 'Sela (hijo de Judá)', 'Nombre personal Sela, tercer hijo de Judá y su esposa cananea Súa (Gn 38:5). Desempeña un papel crucial aunque pasivo en la narrativa de Tamar: Judá prometió a Sela como esposo de Tamar tras la muerte de sus hermanos mayores, pero lo retuvo por miedo (Gn 38:11, 14, 26), provocando la drástica acción de Tamar. Sela aparece en genealogías como ancestro de un clan judahita (Gn 46:12; Nm 26:20; 1 Cr 2:3; 4:21).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (140730, 'spa', 'Llama intensa', 'Los tres usos describen llamas de juicio (Ezequiel 20:47), destrucción del malvado (Job 15:30) e intensidad del amor (Cantares 8:6). El español usa ''llama'' en todos los contextos. El pasaje de Cantares es notable, llamando a la llama del amor ''llama de Yahveh'' (o ''llama poderosa''), elevando la pasión erótica a intensidad divina. Ezequiel y Job la emplean para fuego consumidor de juicio, mientras Cantares redefine esta imagen para el amor ardiente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (140731, 'spa', 'Codorniz', 'Codorniz, ave migratoria pequeña (probablemente coturnix communis) provista milagrosamente como alimento durante la travesía por el desierto. Éxodo 16:13 las introduce junto al maná; Números 11:31-32 describe una caída masiva de codornices seguida de plaga divina contra la murmuración del pueblo. El Salmo 105:40 recuerda la provisión de manera positiva. Estas aves, que migran por el Sinaí en grandes bandadas, se convierten en señal de provisión y advertencia divinas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (140733, 'spa', 'Negligencia administrativa', 'En correspondencia administrativa persa (Esdras 4:22, 6:9) y decretos reales (Daniel 6:4), la palabra funciona como advertencia: ''no haya negligencia'' o ''¿por qué debería crecer el daño?'' La evidencia multilingüe (español ''negligencia,'' inglés ''fail/neglect'') confirma que esto se relaciona con descuido administrativo o incumplimiento del deber. El contexto arameo sugiere lenguaje burocrático formal preocupado por la supervisión y responsabilidad en la administración imperial.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (140737, 'spa', 'Tranquilo, sosegado', 'El sentido adjetival basico: estar en reposo, tranquilo, sin perturbacion. En Job 16:12 el sufriente recuerda su calma anterior antes de la calamidad; en Sal 73:12 los impios prosperos se describen como eternamente tranquilos. Jeremias 49:31 lo aplica a una nacion que habita segura, en paralelo con yoshev lavetach (''morar en seguridad''). El cognado arabe confirma el matiz de calma asentada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (140740, 'spa', 'Quietud, paz (sustantivado)', 'Un uso sustantivado o nominalizado donde el adjetivo funciona como sustantivo significando ''quietud, sosiego''. En 1 Cr 4:40 describe la cualidad de la tierra misma: pastos tranquilos y fertiles, en paralelo con shoqetet (''sin perturbacion''). En Job 20:20 aparece como sustantivo abstracto: el impio no conocio tranquilidad interior. Este desplazamiento de adjetivo a sustantivo refleja una extension semantica natural.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (140742, 'spa', 'Quietud, holgura, prosperidad', 'Sustantivo femenino que cubre el espectro completo desde la tranquilidad bendecida hasta la complacencia peligrosa. Positivamente, describe la seguridad apacible que se pide para Jerusalen (Sal 122:7) y el contentamiento silencioso preferible al conflicto (Pr 17:1). Negativamente, caracteriza la holgura descuidada de los necios rumbo a la ruina (Pr 1:32) y la prosperidad autosatisfecha de Sodoma (Ez 16:49). En Daniel 8:25 y 11:21 adquiere connotaciones de astucia politica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (140750, 'spa', 'Regalo de separación', 'El significado raíz involucra algo dado cuando las personas se separan. En Éxodo 18:2 describe a Séfora siendo enviada ''después de su despedida'' (un despido formal). En 1 Reyes 9:16, Faraón da Gezer como dote a su hija que se casa con Salomón—un regalo de despedida marcando su transición del hogar egipcio al israelita. Miqueas 1:14 personaliza esto: Israel dará ''regalos de despedida'' a Moreset-gat, expresando la pérdida de territorio como una partida dolorosa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (140751, 'spa', 'Paz, ausencia de conflicto', 'Paz como ausencia de conflicto, guerra o contienda: el sentido dominante con la gran mayoría de las ocurrencias (198 veces). Abarca desde Dios concediendo paz en la tierra (Lv 26:6) hasta la bendición aarónica «el Señor te dé paz» (Nm 6:26) y las visiones proféticas de paz cósmica (Is 9:7; 11:6-9). El árabe salām, el español paz, el francés paix y el alemán Friede convergen aquí.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (140753, 'spa', 'Saludo de paz', 'Fórmula de saludo o interrogación de intenciones pacíficas: el uso performativo de שָׁלוֹם como acto de habla. «¿Es paz?» (2 R 9:17-22) pone a prueba si alguien viene como amigo o enemigo. «Paz a ti» (Jue 6:23; 19:20) extiende la bienvenida. El alemán «ist es Friede?» y el árabe «hal salām?» conservan la fórmula interrogativa. Se solapa con el sentido 1 pero funciona pragmáticamente como acto social.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (140756, 'spa', 'Bienestar, prosperidad', 'Bienestar, prosperidad o estado general de la persona: el uso en cadena constructa que pregunta por o se refiere a la condición total de alguien: salud, seguridad y florecimiento. Jacob envía a José a indagar sobre el שָׁלוֹם de sus hermanos y del rebaño (Gn 37:14). David pregunta por el שָׁלוֹם de Joab, el ejército y la guerra (2 S 11:7). El alemán Wohlergehen y el español bienestar desplazan el vocabulario de «paz» a «estado de plenitud».');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (140770, 'spa', 'Aliado, amigo íntimo', 'Persona en paz, amigo o aliado: el uso sustantivado donde שָׁלוֹם designa a un confederado o compañero de confianza. El Salmo 55:20 lamenta la traición de «mi שָׁלוֹם», su amigo íntimo que violó el pacto. Jeremías 20:10 refiere a enemigos que acechan a «los hombres de mi שָׁלוֹם» para que tropiecen. El árabe ḥalīf («aliado») y el español aliado aparecen en las traducciones, confirmando una acepción relacional-personal distinta.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (140772, 'spa', 'Totalidad, plenitud', 'Plenitud o totalidad: el sentido etimológico nuclear que refleja la raíz ש-ל-ם «ser entero». Jeremías 13:19 lee «Judá fue llevada cautiva, toda ella» (שְׁלֵמִים), donde el matiz es el de deportación total y completa. El árabe kāmil («completo») y el inglés completely captan esta acepción rara pero fundacional, que subyace a todos los demás significados: la paz es integridad, el bienestar es integridad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (140779, 'spa', 'Salem, nombre propio', 'Uso como nombre propio o asociado a él: el altar de Gedeón «YHWH-Shalom» (Jue 6:24) y el título mesiánico «Príncipe de Paz» en Isaías 9:6 tratan שָׁלוֹם como atributo divino elevado a la categoría de nombre. Aunque se solapa con el sentido 1, estas ocurrencias funcionan como nombres o epítetos más que como descripciones de un estado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (140787, 'spa', 'Retribución divina', 'Usado principalmente para la justicia retributiva de Dios. Isaías 34:8 empareja ''el año de retribución'' con ''el día de venganza,'' indicando el ajuste de cuentas divino. Oseas 9:7 anuncia ''han llegado los días de retribución'' (paralelo a ''visitación'')—un tiempo cuando Dios retribuye a Israel por la violación del pacto. Miqueas 7:3 muestra la perversión humana: jueces que deberían ejecutar justicia en cambio buscan ''el soborno'' (recompensa corrupta), invirtiendo el concepto de justa retribución.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (140788, 'spa', 'Nombre propio hebreo (''recompensado'' o ''completo,'' de שָׁלֵם) que designa a múlt', 'Nombre propio hebreo (''recompensado'' o ''completo,'' de שָׁלֵם) que designa a múltiples individuos. Los más notables: Salum rey de Israel, cuyo reinado usurpador de un solo mes terminó en asesinato (2 R 15:10-15); Salum hijo de Josías, identificado con el rey Joacaz (Jer 22:11; 1 Cr 3:15); Salum el portero del templo (1 Cr 9:17, 19, 31); un ancestro sacerdotal de Esdras (1 Cr 6:12-13; Esd 7:2); y el esposo de la profetisa Hulda (2 R 22:14; 2 Cr 34:22). En español se transliterado Salum.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (140792, 'spa', 'número cardinal tres', 'El número cardinal tres en sus formas masculina (שָׁלֹשׁ) y femenina (שְׁלֹשָׁה), empleado para contar personas, objetos, períodos de tiempo y medidas. Aparece de forma independiente (Gn 6:10, «tres hijos»), en constructo con sufijos pronominales (Gn 9:19, «tres de ellos») y como componente de numerales compuestos como trece o trescientos (Gn 5:22). Las 431 apariciones designan el mismo valor numérico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (140831, 'spa', 'treinta (número cardinal)', 'El número cardinal treinta empleado en conteos, medidas, fórmulas de edad, cantidades monetarias y expresiones temporales. Abarca la gran mayoría de las apariciones: treinta años (Gn 5:3; 2 S 5:4), treinta codos (Gn 6:15), treinta siclos (Éx 21:32), treinta días (Nm 20:29). Todas las lenguas lo traducen sin ambigüedad: español «treinta», francés «trente», alemán «dreißig».');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (140836, 'spa', 'los Treinta (guerreros)', 'Uso sustantivado y cuasi-titular: «los Treinta», designando el cuerpo militar de élite de David listado en 2 Samuel 23:13, 24 y 1 Crónicas 11-12. Aquí el numeral funciona como título propio de un rango o grupo militar, análogo a «los Tres» (הַשְּׁלֹשָׁה) para los guerreros principales. Español «los treinta» e inglés «the thirty» marcan esta función con el artículo definido, señalando el paso de cantidad a designación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (140840, 'spa', 'tres (lectura anómala)', 'Una aparición anómala en 2 Samuel 23:13 donde las glosas multilingües dan el valor «tres» en lugar de «treinta», reflejando probablemente una variante textual (cf. la antigua confusión entre שְׁלֹשִׁים «treinta» y שְׁלֹשָׁה «tres» en pasajes paralelos). Las glosas entre corchetes en varias lenguas señalan incertidumbre editorial sobre la lectura correcta en este punto.');